  function resetFavoriteEditor(){favoriteEditId=null;favoritePoint=null;$('#favoriteForm').reset();$('#favoriteSelection').textContent='Select a search result to save its location.';$('#favoriteEditorTitle').textContent='Add a favourite';$('#cancelFavoriteEdit').classList.add('hidden');$('#favoriteSuggestions').classList.add('hidden');}
