  async function saveDefaultOrigin(e){e.preventDefault();if(!requireEditor())return;if(!defaultOriginPoint){toast('Select your starting address from the search results.');return;}const name=$('#defaultOriginName').value.trim();if(!name)return;$('#saveDefaultOrigin').disabled=true;try{if(await saveRoutePreferences({...routePreferences,defaultOrigin:{...defaultOriginPoint,name}})){finder.start={...routePreferences.defaultOrigin};$('#finderStart').value=finder.start.name;clearFinderRoute();if(finder.end)getFinderRoute();toast('Default starting point saved to your account.');}}finally{$('#saveDefaultOrigin').disabled=false;}}

  function canEdit(){return Boolean(isCloudReady()&&householdRole==='owner');}
