    $('#entryMemberActions').classList.toggle('hidden',!(session&&!householdId&&entryMode==='owner'));
    if(session&&!householdId&&entryMode==='owner'){$('#entryAuthForm').classList.add('hidden');$('#entryStatus').textContent='You’re signed in. Create your household to get started.';}
