  async function entryInviteSubmit(e){e.preventDefault();const code=$('#entryCode').value.trim().toUpperCase();if(!/^[A-Z0-9]{8,12}$/.test(code)){entryMessage('Enter the 8–12 character invite code you received.');return;}pendingInvite=code;store(keys.pendingInvite,code);showEntryAuth();if(session){entryMessage('Opening your family’s dashboard…');try{await finishEntry();}catch(err){entryMessage(err.message);}}else $('#entryEmail').focus();}
  async function entryAuthSubmit(e){
    e.preventDefault();const button=$('#entryAuthSubmit');button.disabled=true;entryMessage('Connecting…');
    try{
      const email=$('#entryEmail').value.trim(),password=$('#entryPassword').value;
      const data=await authRequest(entryAuthMode==='signup'?'signup':'token?grant_type=password',{email,password});
      if(!data.access_token){entryMessage('Check your email to confirm your account. Then return here and sign in.');entryAuthMode='login';updateEntryAuthMode();return;}
      setSession(data);$('#entryPassword').value='';await finishEntry();
    }catch(err){entryMessage(err.message);}finally{button.disabled=false;}
  }
  function updateEntryAuthMode(){$('#entryAuthSubmit').textContent=entryAuthMode==='signup'?'Create account & continue':'Sign in';$('#entryAuthMode').textContent=entryAuthMode==='signup'?'Already have an account? Sign in':'New here? Create an account';$('#entryPassword').autocomplete=entryAuthMode==='signup'?'new-password':'current-password';}

  let sessionRefresh=null;
  function cloudHeaders(){const headers={apikey:config.key,'Content-Type':'application/json'};const token=session?.access_token||(config.key.split('.').length===3?config.key:null);if(token)headers.Authorization=`Bearer ${token}`;return headers;}
  function unauthorizedMessage(data){const detail=data?.message||data?.msg||data?.error_description||'';return /api.?key/i.test(detail)||!session?'Supabase rejected the API key. In Settings, use the publishable or anon key from the same project as the Project URL.': 'Your sign-in could not be verified. Sign in again. '+detail;}
  async function api(path,{method='GET',body,query='',headers:extraHeaders={}}={}){
    if(!config?.url||!config?.key)throw new Error('Connect a Supabase project first.');
    if(method!=='GET'&&path.startsWith('/rest/v1/')&&!canEdit()&&path!=='/rest/v1/rpc/join_household'&&!(path==='/rest/v1/rpc/create_household'&&entryMode==='owner'&&!householdId))throw new Error('Only the household owner can make changes.');
    if(session?.refresh_token&&session.expires_at&&session.expires_at<=Date.now()/1000+30)await refreshSession();
    const headers={...cloudHeaders(),...extraHeaders};
    let res=await fetch(`${config.url.replace(/\/$/,'')}${path}${query}`,{method,headers,...(body===undefined?{}:{body:JSON.stringify(body)})});
    if(res.status===401 && session?.refresh_token){await refreshSession();headers.Authorization=`Bearer ${session.access_token}`;res=await fetch(`${config.url.replace(/\/$/,'')}${path}${query}`,{method,headers,...(body===undefined?{}:{body:JSON.stringify(body)})});}
    const raw=await res.text();let data=null;try{data=raw?JSON.parse(raw):null;}catch{data=raw;}
    if(!res.ok)throw new Error(res.status===401?unauthorizedMessage(data):(data?.message||data?.msg||data?.hint||`Cloud request failed (${res.status})`));
    if(path.startsWith('/rest/v1/')){cloudHealth='connected';cloudError='';cloudLastSync=new Date().toISOString();store(keys.lastSync,cloudLastSync);updateCloudUI();}
    return data;
  }
  async function refreshSession(){
    if(sessionRefresh)return sessionRefresh;
    sessionRefresh=(async()=>{
      const res=await fetch(`${config.url.replace(/\/$/,'')}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});
      const data=await res.json();
      if(!res.ok){if(res.status===400||res.status===401||res.status===403){const invalidKey=/api.?key/i.test(data.message||data.msg||'');setSession(null);householdId=null;updateCloudUI();throw new Error(invalidKey?unauthorizedMessage(data):'Your sign-in expired. Sign in again in Settings to reconnect.');}throw new Error('Could not refresh your sign-in. Try the connection again.');}
      setSession(data);
    })();
    try{await sessionRefresh;}finally{sessionRefresh=null;}
  }
  function setSession(s){if(!s){householdRole=null;cloudLoaded=false;householdId=null;store(keys.activeHousehold,null);}session=s?{access_token:s.access_token,refresh_token:s.refresh_token,expires_at:s.expires_at||Date.now()/1000+(s.expires_in||3600),user:s.user}:null;store(keys.session,session);}
  async function authRequest(path,body){const res=await fetch(`${config.url.replace(/\/$/,'')}/auth/v1/${path}`,{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw new Error(data.msg||data.message||data.error_description||'Could not authenticate.');return data;}
  async function loadCloud(preferredId=null){
    const user=await api('/auth/v1/user');session.user=user;store(keys.session,session);routePreferences=preferencesFromUser(user);
    const activeId=preferredId||read(keys.activeHousehold,null);
    const members=await api('/rest/v1/household_members',{query:`?select=household_id,role&user_id=eq.${encodeURIComponent(session.user.id)}${activeId?`&household_id=eq.${encodeURIComponent(activeId)}`:''}&limit=1`});
    householdId=members?.[0]?.household_id||null;householdRole=members?.[0]?.role||null;cloudLoaded=false;
    if(householdId){store(keys.activeHousehold,householdId);if(householdRole!=='owner'&&!await viewerAccessReady())throw new Error('The car manager needs to enable protected view-only access. Ask them to run the viewer access update in Settings.');}
    if(!householdId){state.trips=[];state.periods={};$('#authBox').classList.remove('hidden');$('#householdBox').classList.remove('hidden');$('#householdMessage').textContent='Create a household or enter an invite code to share the dashboard.';render();return;}
    $('#householdBox').classList.remove('hidden');
    const [cars,trips,periods]=await Promise.all([
      api('/rest/v1/household_cars',{query:`?select=*&household_id=eq.${householdId}`}),
      api('/rest/v1/trips',{query:`?select=*&household_id=eq.${householdId}&order=journey_date.desc`}),
      api('/rest/v1/monthly_periods',{query:`?select=*&household_id=eq.${householdId}`})
    ]);
    const needsExpenseUpdate=(cars||[]).some(c=>!('tax_enabled' in c)||!('insurance_enabled' in c));$('#expenseSchemaNotice').classList.toggle('hidden',!needsExpenseUpdate);
    const rates=defaultState().rates;for(const c of cars||[]){if(rates.cars[c.car_key]){rates.cars[c.car_key]={efficiency:Number(c.efficiency_l_100km),tax:Number(c.monthly_tax),insurance:Number(c.monthly_insurance),taxEnabled:c.tax_enabled??true,insuranceEnabled:c.insurance_enabled??true};if(c.fuel_price!=null)rates.fuelPrice=Number(c.fuel_price);}}
    state.rates=rates;state.trips=(trips||[]).map(t=>({...t}));state.periods={};for(const p of periods||[])state.periods[p.month_key]={closed_at:p.closed_at,fixed_costs:p.fixed_costs};
    cloudLoaded=true;$('#viewerSetupNotice').classList.toggle('hidden',householdRole!=='owner'||await viewerAccessReady());
    $('#householdMessage').textContent='Your family household is connected. Members with an invite code can see its trips and costs.';
    render();
  }
  async function upsertAllCars(){
    if(!canEdit())return;
    for(const key of ['karl','crossland']){
      const c=carInfo(key),body={household_id:householdId,car_key:key,label:c.name,model_year:c.year,efficiency_l_100km:c.efficiency,monthly_tax:c.tax,monthly_insurance:c.insurance,tax_enabled:c.taxEnabled,insurance_enabled:c.insuranceEnabled,fuel_price:state.rates.fuelPrice};
      const write=()=>api('/rest/v1/household_cars?on_conflict=household_id,car_key',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates,return=minimal'},body});
      try{await write();}catch(err){
        if(!/tax_enabled|insurance_enabled/.test(err.message))throw err;
        $('#expenseSchemaNotice').classList.remove('hidden');
        if(!c.taxEnabled||!c.insuranceEnabled)throw new Error('Add the two expense columns in Supabase before saving expense toggles. See Settings for the SQL update.');
        delete body.tax_enabled;delete body.insurance_enabled;await write();
      }
    }
  }
  async function upsertCloudPeriod(m,closedAt,fixedCosts){await api('/rest/v1/monthly_periods?on_conflict=household_id,month_key',{method:'POST',body:{household_id:householdId,month_key:m,closed_at:closedAt,fixed_costs:fixedCosts},headers:{'Prefer':'resolution=merge-duplicates,return=minimal'}});}
  function showCloudError(err){cloudHealth='error';cloudError=err?.message||'Cloud connection failed.';updateCloudUI();toast(cloudError);console.error(err);if(!cloudLoaded)entryMessage(cloudError);}
  async function checkConnection(){if(!config){cloudHealth='idle';cloudError='';updateCloudUI();toast('No cloud project is configured yet.');return;}cloudHealth='checking';cloudError='';updateCloudUI();try{await api('/rest/v1/household_members',{query:'?select=household_id&limit=0'});if(session){await loadCloud();cloudHealth=householdId?'connected':'account';}else cloudHealth='project';cloudError='';updateCloudUI();toast(session?(householdId?'Database and household are connected.':'Database is reachable; join or create a household.'):'Database is reachable; sign in to sync trips.');}catch(err){showCloudError(err);}}

  function nav(view){if(!canEdit()&&['settings','route','favorites'].includes(view))view='overview';$$('.page').forEach(p=>p.classList.add('hidden'));$(`#${view}View`)?.classList.remove('hidden');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const label={overview:'Overview',agenda:'Agenda',periods:'Monthly periods',settings:'Settings',route:'Route finder',favorites:'Favourite places'}[view]||'Overview';$('#pageCrumb').textContent=label;window.scrollTo({top:0,behavior:'smooth'});if(view==='settings')populateSettings();if(view==='agenda')renderAgenda();if(view==='periods')renderPeriods();if(view==='favorites')renderPlaces();if(view==='route'){initFinderMap();if(!finder.start&&!$('#finderStart').value&&routePreferences.defaultOrigin){finder.start={...routePreferences.defaultOrigin};$('#finderStart').value=finder.start.name;}}}
  function render(){renderOverview();renderAgenda();renderPeriods();populateSettings();renderPlaces();updateCloudUI();applyAccess();}
  function inMonth(t,m){return tripDate(t)?.slice(0,7)===m;}
  function monthTrips(m=state.selectedMonth){return state.trips.filter(t=>inMonth(t,m)).sort((a,b)=>tripDate(a).localeCompare(tripDate(b)));}
  function monthCosts(m=state.selectedMonth){const trips=monthTrips(m),fuel=trips.reduce((a,t)=>a+tripCost(t),0),fixed=state.periods[m]?.fixed_costs,active=activeFixedCosts(),tax=fixed?.tax??active.tax,insurance=fixed?.insurance??active.insurance;return {trips,fuel,tax,insurance,total:fuel+tax+insurance,distance:trips.reduce((a,t)=>a+tripDistance(t),0)};}
  function renderOverview(){
    const m=state.selectedMonth, c=monthCosts(m);$('#monthTitle').textContent=monthLabel(m);$('#monthSubtitle').textContent=m===currentMonth?'Current monthly period':periodClosed(m)?'Closed monthly period':'Monthly period';$('#chartMonth').textContent=monthLabel(m,false);$('#periodStateText').textContent=periodClosed(m)?'Period closed':'Period open';$('#closePeriod').textContent=periodClosed(m)?'Reopen month':'Close month';$('#monthTotal').textContent=money(c.total);$('#fuelTotal').textContent=money(c.fuel);$('#fixedTotal').textContent=money(c.tax+c.insurance);$('#tripCount').textContent=`${c.trips.length} ${c.trips.length===1?'journey':'journeys'}`;$('#distanceTotal').textContent=`${Math.round(c.distance)} km`;$('#donutTotal').textContent=money(c.total);$('#legendFuel').textContent=money(c.fuel);$('#legendTax').textContent=money(c.tax);$('#legendInsurance').textContent=money(c.insurance);const den=c.total||1,a=c.fuel/den*360,b=c.tax/den*360,d=c.insurance/den*360;$('#costDonut').style.background=`conic-gradient(var(--blue) 0deg ${a}deg,var(--teal) ${a}deg ${a+b}deg,var(--orange) ${a+b}deg ${a+b+d}deg,var(--line) ${a+b+d}deg 360deg)`;
    const list=$('#journeyList');list.replaceChildren();const sorted=[...c.trips].sort((a,b)=>tripDate(a).localeCompare(tripDate(b))).slice(0,5);$('#emptyJourneys').classList.toggle('hidden',sorted.length>0);for(const t of sorted)list.append(createTripRow(t));
    $('#closePeriod').disabled=false;$('#closePeriod').style.opacity='1';
  }
  function createTripRow(t){const row=document.createElement('div');row.className='journey-item';const date=dateObj(tripDate(t)),status=tripDate(t)<new Date().toISOString().slice(0,10)?'Completed':'Upcoming';row.innerHTML=`<div class="journey-date"><b>${date.getDate()}</b><small>${new Intl.DateTimeFormat('en-GB',{month:'short'}).format(date)}</small></div><div class="journey-route">${tripRouteMarkup(t)}<div class="route-caption"><span class="route-car">${carInfo(tripCar(t)).name.replace('Opel ','')}</span><i class="mini-dot"></i><span>${Math.round(tripDistance(t))} km · ${t.trip_type==='return'||t.tripType==='return'?'return':'single'}</span><i class="mini-dot"></i><span>${status}</span></div></div><div class="journey-cost"><b>${money(tripCost(t))}</b><small>fuel estimate</small></div><button type="button" class="delete-trip" data-delete-trip="${esc(t.id)}" title="Remove journey" aria-label="Remove ${esc(tripFrom(t))} to ${esc(tripTo(t))}">×</button>`;return row;}
  function renderAgenda(){const m=state.selectedMonth,$list=$('#agendaList');$('#agendaMonthHeading').textContent=monthLabel(m);$list.replaceChildren();const trips=monthTrips(m);$('#agendaEmpty').classList.toggle('hidden',trips.length>0);for(const t of trips){const row=document.createElement('div');row.className='full-trip';const date=dateObj(tripDate(t)),status=tripDate(t)<new Date().toISOString().slice(0,10)?'Completed':'Upcoming';row.innerHTML=`<div class="journey-date"><b>${date.getDate()}</b><small>${new Intl.DateTimeFormat('en-GB',{month:'short'}).format(date)}</small></div><div class="journey-route">${tripRouteMarkup(t)}<div class="route-caption">${carInfo(tripCar(t)).name} · ${Math.round(tripDistance(t))} km · ${t.trip_type==='return'||t.tripType==='return'?'return':'single'}</div></div><span class="trip-status ${status==='Completed'?'done':''}">${status}</span><div class="journey-cost"><b>${money(tripCost(t))}</b><small>fuel estimate</small></div><button type="button" class="delete-trip" data-delete-trip="${esc(t.id)}" title="Remove journey" aria-label="Remove ${esc(tripFrom(t))} to ${esc(tripTo(t))}">×</button>`;$list.append(row);}}
  function allMonths(){const ms=new Set([currentMonth,...Object.keys(state.periods),...state.trips.map(t=>tripDate(t)?.slice(0,7)).filter(Boolean)]);return [...ms].sort((a,b)=>b.localeCompare(a));}
  function renderPeriods(){const box=$('#periodList');box.replaceChildren();for(const m of allMonths()){const c=monthCosts(m),row=document.createElement('div');row.className='period-row';row.innerHTML=`<div><h3>${monthLabel(m)}</h3><p>${c.trips.length} ${c.trips.length===1?'journey':'journeys'} · ${Math.round(c.distance)} km${periodClosed(m)?' · closed':''}</p></div><div class="period-total"><b>${money(c.total)}</b><small>estimated total</small></div><div class="period-actions"><button class="mini-button" data-export="${m}">PDF invoice</button><button class="mini-button" data-print="${m}">Print</button></div>`;box.append(row);}}
  function populateSettings(){const r=state.rates;$('#fuelPriceInput').value=r.fuelPrice;$('#karlEfficiency').value=r.cars.karl.efficiency;$('#karlTax').value=r.cars.karl.tax;$('#karlInsurance').value=r.cars.karl.insurance;$('#karlTaxEnabled').checked=r.cars.karl.taxEnabled;$('#karlInsuranceEnabled').checked=r.cars.karl.insuranceEnabled;$('#crossEfficiency').value=r.cars.crossland.efficiency;$('#crossTax').value=r.cars.crossland.tax;$('#crossInsurance').value=r.cars.crossland.insurance;$('#crossTaxEnabled').checked=r.cars.crossland.taxEnabled;$('#crossInsuranceEnabled').checked=r.cars.crossland.insuranceEnabled;if(config){$('#supabaseUrl').value=config.url||'';$('#supabaseKey').value=config.key||'';}else{$('#supabaseUrl').value='';$('#supabaseKey').value='';}}
  function updateCloudUI(){const online=isCloudReady(),reachable=['project','account','connected'].includes(cloudHealth),pill=$('#connectionPill');let label,detail;if(cloudHealth==='checking'){label='Checking…';detail='Checking the cloud database now.';}else if(cloudHealth==='error'){label='Connection issue';detail=cloudError||'Could not reach the cloud database.';}else if(!config){label='Demo mode';detail='Trips are saved only in this browser.';}else if(cloudHealth==='project'){label='Server reachable';detail='The database API answered. Sign in to sync trips.';}else if(!session){label='Project saved';detail='Project details are saved. Check the connection before syncing.';}else if(!householdId){label='Signed in';detail='Cloud reached. Create or join your household to sync trips.';}else if(online){label='Connected';detail='Cloud database and household are ready to sync.';}else{label='Cloud configured';detail='Check the server connection.';}pill.classList.toggle('online',reachable||online);pill.classList.toggle('error',cloudHealth==='error');$('.sync-dot').classList.toggle('online',reachable||online);$('.sync-dot').classList.toggle('error',cloudHealth==='error');$('#connectionText').textContent=label;$('#syncTitle').textContent=label;$('#syncSub').textContent=cloudLastSync?`Last sync ${new Date(cloudLastSync).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`:'Tap to check server';$('#cloudStatus').classList.toggle('online',reachable||online);$('#cloudStatus').classList.toggle('error',cloudHealth==='error');$('#cloudStatusText').textContent=detail;$('#cloudLastSync').textContent=cloudLastSync?`Last successful database request: ${new Date(cloudLastSync).toLocaleString()}`:'';$('#checkCloudConnection').disabled=cloudHealth==='checking';$('#checkCloudConnection').textContent=cloudHealth==='checking'?'Checking…':'Check connection';$('#authBox').classList.toggle('hidden',!config);$('#authForm').classList.toggle('hidden',Boolean(session));$('#householdBox').classList.toggle('hidden',!session);$('#signOut').classList.toggle('hidden',!session);if(session&&!householdId)$('#householdBox').classList.remove('hidden');applyAccess();}
  function applyTheme(){document.body.classList.toggle('dark-mode',theme==='dark');const b=$('#themeToggle');b.textContent=theme==='dark'?'☀':'☾';b.title=theme==='dark'?'Switch to light mode':'Switch to dark mode';b.setAttribute('aria-label',b.title);document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#080808':'#f5f5f3';}
  async function removeTrip(id){if(!requireEditor())return;const t=state.trips.find(x=>String(x.id)===String(id));if(!t)return;if(!window.confirm(`Remove the journey from ${tripFrom(t)} to ${tripTo(t)}?`))return;if(isCloudReady()){try{await api('/rest/v1/trips',{method:'DELETE',query:`?id=eq.${encodeURIComponent(id)}&household_id=eq.${encodeURIComponent(householdId)}`});}catch(err){showCloudError(err);return;}}state.trips=state.trips.filter(x=>String(x.id)!==String(id));saveDemo();render();toast('Journey removed from the agenda.');}
  function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

  function shiftMonth(delta){const [y,m]=state.selectedMonth.split('-').map(Number);const d=new Date(y,m-1+delta,1);state.selectedMonth=monthKey(d);saveDemo();render();}
  function openDrawer(){if(!requireEditor())return;if(periodClosed(state.selectedMonth)){toast('This period is closed. Reopen it before adding trips.');return;}$('#journeyBackdrop').classList.remove('hidden');$('#journeyDrawer').classList.add('open');$('#journeyDrawer').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';resetDrawer();}
  function closeDrawer(){ $('#journeyBackdrop').classList.add('hidden');$('#journeyDrawer').classList.remove('open');$('#journeyDrawer').setAttribute('aria-hidden','true');document.body.style.overflow='';}
  function resetDrawer(){selectedCar='karl';tripType='single';oneWayKm=null;routeStart=routePreferences.defaultOrigin?{...routePreferences.defaultOrigin}:null;routeEnd=null;$$('.pick-car').forEach(b=>b.classList.toggle('selected',b.dataset.car===selectedCar));$$('[data-trip-type]').forEach(b=>b.classList.toggle('selected',b.dataset.tripType===tripType));$('#startInput').value=routeStart?.name||'';$('#destinationInput').value='';$('#journeyDate').value=currentMonth===state.selectedMonth?today.toISOString().slice(0,10):`${state.selectedMonth}-15`;$('#tripNote').value='';$('#distanceLabel').textContent='Choose a destination';$('#continueJourney').disabled=true;$('#journeyStepOne').classList.remove('hidden');$('#journeyStepTwo').classList.add('hidden');$('#stepDot1').classList.add('active');$('#stepDot2').classList.remove('active');$('#stepLabel').textContent='CAR & ROUTE';$('#manualDistance').classList.add('hidden');$('#mapHint').classList.remove('hidden');if(map&&routeLayer){map.removeLayer(routeLayer);routeLayer=null;}if(map&&markerLayer){map.removeLayer(markerLayer);markerLayer=null;}if(!map&&window.L){map=L.map('routeMap',{zoomControl:false,attributionControl:false}).setView([51.5,4.3],8);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(map);setTimeout(()=>map.invalidateSize(),80);}}
  async function searchPlaces(q){if(!q||q.length<3)return[];const url=`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=5&q=${encodeURIComponent(q)}`;const r=await fetch(url,{headers:{'Accept-Language':'en'}});if(!r.ok)throw new Error('Place search is temporarily unavailable.');return r.json();}
  function setupPlaceSearch(input){let timer;input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(input.id==='startInput')routeStart=null;else routeEnd=null;{oneWayKm=null;$('#continueJourney').disabled=true;$('#distanceLabel').textContent='Searching…';}if(q.length<3)return;timer=setTimeout(async()=>{try{const rows=await searchPlaces(q);showSuggestions(rows,input);}catch(err){$('#distanceLabel').textContent='Enter distance manually';}},450);});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=$('.suggestion');if(first)first.click();else if(input.id==='destinationInput')$('#editDistance').click();}});}
  function showSuggestions(rows,input){const box=$('#suggestions');box.replaceChildren();if(!rows.length){box.classList.add('hidden');return;}for(const p of rows){const b=document.createElement('button');b.type='button';b.className='suggestion';b.textContent=p.display_name;b.addEventListener('click',()=>{input.value=placeName(p.display_name);box.classList.add('hidden');const point={lat:Number(p.lat),lon:Number(p.lon),label:p.display_name,name:placeName(p.display_name)};if(input.id==='startInput'){routeStart=point;if(routeEnd)getRoadRoute();else $('#destinationInput').focus();}else{routeEnd=point;getRoadRoute();}});box.append(b);}box.classList.remove('hidden');}
  async function getRoadRoute(){if(!routeEnd){return;}if(!routeStart){try{const r=await searchPlaces($('#startInput').value);if(r[0])routeStart={lat:Number(r[0].lat),lon:Number(r[0].lon),label:r[0].display_name};}catch{}}
    if(!routeStart){$('#distanceLabel').textContent='Enter start and distance';$('#manualDistance').classList.remove('hidden');return;}
    $('#distanceLabel').textContent='Calculating…';$('#mapHint').classList.add('hidden');
    try{const r=await fetch(`https://router.project-osrm.org/route/v1/driving/${routeStart.lon},${routeStart.lat};${routeEnd.lon},${routeEnd.lat}?overview=full&geometries=geojson`);const data=await r.json();if(!data.routes?.[0])throw new Error('No road route');oneWayKm=data.routes[0].distance/1000;drawMap(data.routes[0].geometry.coordinates);$('#distanceLabel').textContent=`${oneWayKm.toFixed(1)} km one way`;$('#continueJourney').disabled=false;}catch{const km=haversine(routeStart.lat,routeStart.lon,routeEnd.lat,routeEnd.lon)*1.25;oneWayKm=km;drawMap([[routeStart.lon,routeStart.lat],[routeEnd.lon,routeEnd.lat]]);$('#distanceLabel').textContent=`~${km.toFixed(1)} km estimated`;$('#continueJourney').disabled=false;}}
  function haversine(lat1,lon1,lat2,lon2){const rad=x=>x*Math.PI/180,R=6371,dLat=rad(lat2-lat1),dLon=rad(lon2-lon1),a=Math.sin(dLat/2)**2+Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
  function drawMap(coords){if(!map||!window.L)return;$('#mapHint').classList.add('hidden');const latlngs=coords.map(p=>[p[1],p[0]]);if(routeLayer)map.removeLayer(routeLayer);if(markerLayer)map.removeLayer(markerLayer);routeLayer=L.polyline(latlngs,{color:'#2870f4',weight:4,opacity:.86}).addTo(map);markerLayer=L.layerGroup([L.circleMarker(latlngs[0],{radius:5,color:'#fff',weight:2,fillColor:'#2870f4',fillOpacity:1}),L.circleMarker(latlngs.at(-1),{radius:5,color:'#fff',weight:2,fillColor:'#44b496',fillOpacity:1})]).addTo(map);map.fitBounds(routeLayer.getBounds(),{padding:[22,22]});}
  function calculatedDistance(){return oneWayKm*(tripType==='return'?2:1);}
  function showReview(){const km=calculatedDistance(),c=carInfo(selectedCar),litres=km*c.efficiency/100,cost=litres*state.rates.fuelPrice;$('#reviewStart').textContent=$('#startInput').value;$('#reviewDestination').textContent=$('#destinationInput').value;$('#reviewCar').textContent=c.name;$('#reviewDistance').textContent=`${km.toFixed(1)} km · ${tripType}`;$('#reviewDate').textContent=dateLabel($('#journeyDate').value);$('#costDistance').textContent=`${km.toFixed(1)} km`;$('#fuelLitres').textContent=`${litres.toFixed(2)} L`;$('#efficiencyNote').textContent=`at ${c.efficiency} L / 100 km`;$('#priceNote').textContent=`at ${money(state.rates.fuelPrice)} / litre`;$('#journeyFuelCost').textContent=money(cost);$('#journeyCostTotal').textContent=money(cost);$('#journeyStepOne').classList.add('hidden');$('#journeyStepTwo').classList.remove('hidden');$('#stepDot2').classList.add('active');$('#stepLabel').textContent='REVIEW COSTS';}
  async function persistTrip(t){if(!requireEditor())return false;if(isCloudReady()){try{const result=await api('/rest/v1/trips?select=*',{method:'POST',body:t});state.trips.unshift(result?.[0]||t);return true;}catch(err){showCloudError(err);return false;}}state.trips.push({...t,date:t.journey_date,car:t.car_key,start:t.start_label,destination:t.destination_label,tripType:t.trip_type,distanceKm:t.distance_km,fuelCost:t.fuel_cost});saveDemo();return true;}
  async function saveTrip(e){e.preventDefault();const date=$('#journeyDate').value;if(!date||!oneWayKm)return;const km=calculatedDistance(),c=carInfo(selectedCar),litres=km*c.efficiency/100,cost=litres*state.rates.fuelPrice;const t={id:crypto.randomUUID?.()||`trip-${Date.now()}`,household_id:householdId,created_by:session?.user?.id||null,car_key:selectedCar,start_label:window.RoadnotePlaces.pack(routeStart,$('#startInput').value.trim()),destination_label:window.RoadnotePlaces.pack(routeEnd,$('#destinationInput').value.trim()),journey_date:date,trip_type:tripType,distance_km:Number(km.toFixed(2)),fuel_litres:Number(litres.toFixed(3)),fuel_price_per_litre:state.rates.fuelPrice,fuel_cost:Number(cost.toFixed(2)),efficiency_l_100km:c.efficiency,note:$('#tripNote').value.trim()||null};if(!await persistTrip(t))return;
    closeDrawer();render();nav('overview');toast(isCloudReady()?'Journey saved to your shared agenda.':'Journey saved in this browser demo. Connect cloud storage to sync it.');}

  function initFinderMap(){if(!window.L)return;if(!finder.map){finder.map=L.map('routeFinderMap',{zoomControl:true,attributionControl:false}).setView([51.5,4.3],8);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(finder.map);}setTimeout(()=>finder.map.invalidateSize(),80);}
  function finderPoint(p){return {lat:Number(p.lat),lon:Number(p.lon),label:p.display_name,name:placeName(p.display_name)};}
  function finderSuggest(box,rows,which){box.replaceChildren();if(!rows.length){box.classList.add('hidden');return;}for(const p of rows){const b=document.createElement('button');b.type='button';b.className='suggestion';b.textContent=p.display_name;b.addEventListener('click',()=>{const point=finderPoint(p);if(which==='start'){finder.start=point;$('#finderStart').value=point.name;$('#finderStartSuggestions').classList.add('hidden');if(finder.end)getFinderRoute();else $('#finderDestination').focus();}else{finder.end=point;$('#finderDestination').value=point.name;$('#finderDestinationSuggestions').classList.add('hidden');getFinderRoute();}});box.append(b);}box.classList.remove('hidden');}
  function setupFinderInput(input,which){let timer;input.addEventListener('input',()=>{clearTimeout(timer);if(which==='start')finder.start=null;else finder.end=null;finder.distance=null;$('#finderAdd').disabled=true;$('#finderDistance').textContent='Searching…';$('#finderCost').textContent='—';$('#finderManual').classList.add('hidden');if(finder.line){finder.map.removeLayer(finder.line);finder.line=null;}if(finder.markers){finder.map.removeLayer(finder.markers);finder.markers=null;}$('#finderMapHint').classList.remove('hidden');$('#finderMapCaption').textContent='Search for a destination to preview the drive.';if(input.value.trim().length<3)return;timer=setTimeout(async()=>{try{finderSuggest($(`#finder${which==='start'?'Start':'Destination'}Suggestions`),await searchPlaces(input.value.trim()),which);}catch{$('#finderManual').classList.remove('hidden');$('#finderDistance').textContent='Route lookup unavailable';}},500);});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=$(`#finder${which==='start'?'Start':'Destination'}Suggestions .suggestion`);if(first)first.click();}});}
  async function getFinderRoute(){if(!finder.end)return;if(!finder.start){try{const rows=await searchPlaces($('#finderStart').value);if(rows[0])finder.start=finderPoint(rows[0]);}catch{}}
    if(!finder.start){$('#finderManual').classList.remove('hidden');$('#finderDistance').textContent='Set a starting point';return;}
    $('#finderDistance').textContent='Calculating route…';$('#finderMapHint').classList.add('hidden');$('#finderMapCaption').textContent='Finding the best available road route…';initFinderMap();
    try{const r=await fetch(`https://router.project-osrm.org/route/v1/driving/${finder.start.lon},${finder.start.lat};${finder.end.lon},${finder.end.lat}?overview=full&geometries=geojson`),data=await r.json();if(!data.routes?.[0])throw new Error('No road route');finder.distance=data.routes[0].distance/1000;drawFinderMap(data.routes[0].geometry.coordinates);}
    catch{finder.distance=haversine(finder.start.lat,finder.start.lon,finder.end.lat,finder.end.lon)*1.25;drawFinderMap([[finder.start.lon,finder.start.lat],[finder.end.lon,finder.end.lat]]);$('#finderMapCaption').textContent='Road route unavailable; showing a distance estimate.';}updateFinderEstimate();}
  function drawFinderMap(coords){if(!finder.map)return;$('#finderMapHint').classList.add('hidden');const points=coords.map(p=>[p[1],p[0]]);if(finder.line)finder.map.removeLayer(finder.line);if(finder.markers)finder.map.removeLayer(finder.markers);finder.line=L.polyline(points,{color:'#2870f4',weight:5,opacity:.88}).addTo(finder.map);finder.markers=L.layerGroup([L.circleMarker(points[0],{radius:6,color:'#fff',weight:2,fillColor:'#2870f4',fillOpacity:1}),L.circleMarker(points.at(-1),{radius:6,color:'#fff',weight:2,fillColor:'#44b496',fillOpacity:1})]).addTo(finder.map);finder.map.fitBounds(finder.line.getBounds(),{padding:[32,32]});$('#finderMapCaption').textContent=`${finder.start.name||placeName(finder.start.label)} to ${finder.end.name||placeName(finder.end.label)}`;}
  function updateFinderEstimate(){if(!finder.distance)return;const car=carInfo(finder.car),totalKm=finder.distance*(finder.tripType==='return'?2:1),litres=totalKm*car.efficiency/100,cost=litres*state.rates.fuelPrice;$('#finderDistance').textContent=`${totalKm.toFixed(1)} km${finder.tripType==='return'?' return':''}`;$('#finderCost').textContent=money(cost);$('#finderAdd').disabled=!$('#finderDate').value;}
  async function addFinderTrip(){if(!requireEditor())return;if(!finder.distance||!$('#finderStart').value.trim()||!$('#finderDestination').value.trim())return;if(periodClosed($('#finderDate').value.slice(0,7))){toast('That month is closed. Reopen it before adding journeys.');return;}const car=carInfo(finder.car),distance=finder.distance*(finder.tripType==='return'?2:1),litres=distance*car.efficiency/100,cost=litres*state.rates.fuelPrice,t={id:crypto.randomUUID?.()||`trip-${Date.now()}`,household_id:householdId,created_by:session?.user?.id||null,car_key:finder.car,start_label:window.RoadnotePlaces.pack(finder.start,$('#finderStart').value.trim()),destination_label:window.RoadnotePlaces.pack(finder.end,$('#finderDestination').value.trim()),journey_date:$('#finderDate').value,trip_type:finder.tripType,distance_km:Number(distance.toFixed(2)),fuel_litres:Number(litres.toFixed(3)),fuel_price_per_litre:state.rates.fuelPrice,fuel_cost:Number(cost.toFixed(2)),efficiency_l_100km:car.efficiency,note:null};if(!await persistTrip(t))return;state.selectedMonth=t.journey_date.slice(0,7);if(!isCloudReady())saveDemo();render();nav('agenda');toast(isCloudReady()?'Route added to your shared agenda.':'Route added to the demo agenda.');}

  function exportMonth(m){
    try{
      if(!window.jspdf?.jsPDF||!window.RoadnoteInvoice)throw new Error('The PDF generator could not load. Reload and try again.');
      const c=monthCosts(m);
      const doc=window.RoadnoteInvoice.create({jsPDF:window.jspdf.jsPDF,month:m,costs:c,details:invoiceDetails,closed:periodClosed(m),trips:c.trips.map(t=>({date:tripDate(t),destination:tripToShort(t),car:tripCar(t),distance:tripDistance(t),cost:tripCost(t),returnTrip:(t.trip_type||t.tripType)==='return'}))});
      doc.save(`roadnote-invoice-${m}.pdf`);toast('Your PDF invoice is ready.');
    }catch(err){toast(err.message);console.error(err);}
  }
  function printMonth(m){const c=monthCosts(m),trips=c.trips;const win=window.open('','_blank');if(!win){toast('Allow pop-ups to print the overview.');return;}const body=trips.length?trips.map(t=>`<tr><td>${esc(dateLabel(tripDate(t)))}</td><td>${esc(carInfo(tripCar(t)).name)}</td><td>${esc(tripFromShort(t))} → ${esc(tripToShort(t))}</td><td>${Math.round(tripDistance(t))} km</td><td>${money(tripCost(t))}</td></tr>`).join(''):'<tr><td colspan="5">No journeys recorded this month.</td></tr>';win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Roadnote · ${monthLabel(m)}</title><style>body{font:14px Arial,sans-serif;color:#20334c;padding:38px;max-width:900px;margin:auto}h1{font-size:25px;margin:0 0 4px}.muted{color:#748399}table{width:100%;border-collapse:collapse;margin:24px 0}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #dfe5ec;font-size:12px}th{background:#f3f6fa}.summary{width:340px;margin-left:auto}.summary div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #e5eaf0}.summary .total{font-weight:bold;font-size:16px;border:0}.closed{margin-top:20px;font-size:11px;color:#75849a}@media print{body{padding:0}}</style></head><body><h1>Monthly car cost overview</h1><div class="muted">${monthLabel(m)} · ${periodClosed(m)?'Closed':'Open'} period</div><table><thead><tr><th>Date</th><th>Car</th><th>Journey</th><th>Distance</th><th>Fuel estimate</th></tr></thead><tbody>${body}</tbody></table><div class="summary"><div><span>Fuel estimates</span><b>${money(c.fuel)}</b></div><div><span>Road tax</span><b>${money(c.tax)}</b></div><div><span>Insurance</span><b>${money(c.insurance)}</b></div><div class="total"><span>Estimated total</span><b>${money(c.total)}</b></div><div><span>Total distance</span><b>${Math.round(c.distance)} km</b></div></div><p class="closed">Fuel expenses are estimates based on distance and saved consumption rates. Fixed tax and insurance are included as monthly household costs.</p><script>window.onload=()=>window.print()</script></body></html>`);win.document.close();}

  async function cloudConnect(e){e.preventDefault();const url=$('#supabaseUrl').value.trim().replace(/\/$/,''),key=$('#supabaseKey').value.trim();if(!url.startsWith('https://')||!key){toast('Enter a valid Supabase URL and publishable key.');return;}if(config?.url!==url){setSession(null);householdId=null;cloudLastSync='';store(keys.lastSync,'');}config={url,key};cloudHealth='idle';cloudError='';store(keys.config,config);await checkConnection();}
  async function authSubmit(e){e.preventDefault();if(!config){toast('Connect a cloud project first.');return;}const email=$('#authEmail').value.trim(),password=$('#authPassword').value;try{if(authMode==='signup'){const d=await authRequest('signup',{email,password});if(!d.access_token){toast('Check your email to confirm your account, then sign in.');authMode='login';$('#authSubmit').textContent='Sign in';return;}setSession(d);}else{const d=await authRequest('token?grant_type=password',{email,password});setSession(d);}await loadCloud();if(canEdit()){await upsertAllCars();await loadCloud();}updateCloudUI();render();toast('Signed in.');}catch(err){showCloudError(err);}}
  async function createHousehold(){try{entryMode='owner';const rows=await api('/rest/v1/rpc/create_household',{method:'POST',body:{household_name:`${session.user.email?.split('@')[0]||'Family'} household`}});householdId=typeof rows==='string'?rows:(rows?.id||rows?.[0]?.id);await loadCloud(householdId);await upsertAllCars();await loadCloud();render();toast('Household created. You can now invite your mom.');}catch(err){showCloudError(err);}}
  async function createInviteCode(){if(!canEdit())throw new Error('Only the household owner can create invites.');
    try{
      const data=await api('/rest/v1/rpc/create_household_invite',{method:'POST',body:{target_household_id:householdId}});
      const code=typeof data==='string'?data:(data?.code||data?.[0]?.code);
      if(!code)throw new Error('The server did not return an invite code. Try again.');
      return code;
    }catch(err){
      if(!/gen_random_bytes.*does not exist/i.test(err.message))throw err;
      // Older installations have a broken RPC. This insert still uses the member-only RLS policy.
      for(let attempt=0;attempt<3;attempt++){
        const bytes=crypto.getRandomValues(new Uint8Array(6));
        const code=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();
        try{await api('/rest/v1/household_invites',{method:'POST',headers:{Prefer:'return=minimal'},body:{household_id:householdId,created_by:session.user.id,code}});return code;}
        catch(insertError){if(/duplicate key|unique constraint/i.test(insertError.message)&&attempt<2)continue;$('#inviteFix').classList.remove('hidden');throw new Error('Your database invite function needs an update. Run the invite repair SQL linked below, then try again.');}
      }
    }
  }
  async function createInvite(){
    const button=$('#inviteHousehold');button.disabled=true;button.textContent='Creating…';$('#inviteResult').classList.add('hidden');$('#inviteShareBox').classList.add('hidden');$('#inviteFix').classList.add('hidden');
    try{if(!isCloudReady())throw new Error('Sign in and connect to a household first.');const code=await createInviteCode();$('#inviteResult').textContent=code;$('#inviteResult').classList.remove('hidden');$('#inviteShareLink').value=`${location.origin}${location.pathname}?invite=${encodeURIComponent(code)}`;$('#inviteShareBox').classList.remove('hidden');toast('Invite code ready. It expires in 7 days.');}
    catch(err){showCloudError(err);}finally{button.disabled=false;button.textContent='Create invite code';}
  }
